import{_ as e,o as t,c as s,ak as i}from"./chunks/framework.DKi5cyCJ.js";const m=JSON.parse('{"title":"定时器","description":"APB 分频不为 1 时定时器时钟乘 2、ARR 加 1、输入捕获","frontmatter":{"title":"定时器","description":"APB 分频不为 1 时定时器时钟乘 2、ARR 加 1、输入捕获","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-定时器.md","filePath":"pages/blog/2026-10-20-定时器.md"}'),l={name:"pages/blog/2026-10-20-定时器.md"};function p(o,a,r,n,d,c){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="定时器-时钟倍频与输入捕获" tabindex="-1">定时器：时钟倍频与输入捕获 <a class="header-anchor" href="#定时器-时钟倍频与输入捕获" aria-label="Permalink to &quot;定时器：时钟倍频与输入捕获&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a> · <a href="/demos/timer-timing.html" target="_blank">时序动画</a></p></blockquote><div class="blog-demo-frame"><iframe src="/demos/timer-timing.html?embed=1" title="定时器时序动态演示" loading="lazy"></iframe></div><p>通用定时器是带预分频的计数器，加上比较、捕获和从模式。更新中断做周期任务，输出比较产生 <a href="/pages/blog/2026-10-20-PWM.html">PWM</a>，输入捕获量脉宽。</p><h2 id="时钟" tabindex="-1">时钟 <a class="header-anchor" href="#时钟" aria-label="Permalink to &quot;时钟&quot;">​</a></h2><p>STM32F4 / APM32F4 上，定时器挂在 APB，但时钟不总是等于 APB：</p><ul><li>APB 分频系数是 1：定时器时钟 = APB</li><li>分频系数不是 1：定时器时钟 = 2 × APB</li></ul><p>168 MHz 系统、APB1 = 42 MHz 时，TIM2 的时钟是 84 MHz。SysTick 用内核时钟或它的 8 分频，不要套用这条规则。</p><p>向上计数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>计数频率 = f_tim / (PSC + 1)</span></span>
<span class="line"><span>更新周期 = (PSC + 1) × (ARR + 1) / f_tim</span></span></code></pre></div><p>从 0 计到 ARR，一共 ARR+1 个计数。84 MHz、PSC = 83、ARR = 999 时，更新周期是 1 ms。</p><p>ARR 和比较值默认有预装载，要等更新事件才生效。初始化时可以软件触发一次更新来装载预分频，同时把由此产生的更新标志清掉。只开 NVIC 不开定时器中断使能，不会进中断。TIM1 的更新中断号不是 TIM2 那种单一通道。</p><p>清标志时用赋值清掉指定位。对状态寄存器做读改写，可能把刚置位的其他标志一起清掉。</p><h2 id="输入捕获" tabindex="-1">输入捕获 <a class="header-anchor" href="#输入捕获" aria-label="Permalink to &quot;输入捕获&quot;">​</a></h2><p>上升沿把计数器锁进比较寄存器，再捕下降沿，差值乘计数周期就是高电平时间。中间若溢出，要补上 ARR+1。打开输入滤波，否则毛刺会被当成边沿。误差至少 ±1 个计数。</p><p>周期刚好是设置值两倍时，优先检查有没有把定时器时钟当成 APB、漏了乘 2。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>`,17)])])}const _=e(l,[["render",p]]);export{m as __pageData,_ as default};
